# Full text render of both sheets from the recalculated workbook to confirm
# every formula displays a value and all labels are readable.
from openpyxl import load_workbook
wb = load_workbook('/tmp/recalc/rental_event_log.xlsx', data_only=True)

def fmt(v):
    if v is None: return ''
    if isinstance(v, float): return f'{v:.2f}' if v != int(v) else str(int(v))
    return str(v)

for sh in wb.sheetnames:
    ws = wb[sh]
    print(f'========================= {sh} =========================')
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
        cells = [f'{c.coordinate}={fmt(c.value)}' for c in row if c.value is not None]
        if cells:
            print(' | '.join(cells))
    print()
